    10	
    11	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    12	public final class ReservationService {
    13	
    14	    static final String HOTEL_NAME = "Pousada Maré Alta";
    15	
    16	    private final Rooms rooms;
    17	    private final ReservationStore store;
    18	    private final PriceCalculator priceCalculator;
    19	    private final EmailSender emailSender;
    20	    private final List<ReservationNotification> notifications;
    21	
    22	    public ReservationService(
    23	            Rooms rooms,
    24	            ReservationStore store,
    25	            PriceCalculator priceCalculator,
    26	            EmailSender emailSender,
    27	            List<ReservationNotification> notifications) {
    28	        this.rooms = rooms;
    29	        this.store = store;
    30	        this.priceCalculator = priceCalculator;
    31	        this.emailSender = emailSender;
    32	        this.notifications = notifications;
    33	    }
    34	
    35	    public synchronized Reservation create(NewReservation request) {
    36	        if (!request.checkOut().isAfter(request.checkIn())) {
    37	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    38	        }
    39	        if (request.guests() < 1) {
    40	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    41	        }
    42	        Room room = rooms.find(request.roomNumber())
    43	                .orElseThrow(() -> new HotelException(
    44	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    45	        if (request.guests() > room.capacity()) {
    46	            throw new HotelException(
    47	                    ErrorCode.CAPACITY_EXCEEDED,
    48	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    49	        }
    50	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    51	            throw new HotelException(
    52	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    53	        }
    54	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    55	        return store.add(request, price);
    56	    }
    57	
    58	    public Reservation find(long reservationId) {
    59	        return store.find(reservationId)
    60	                .orElseThrow(() -> new HotelException(
    61	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    62	    }
    63	
    64	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    65	    public synchronized Reservation confirm(long reservationId) {
    66	        Reservation reservation = find(reservationId);
    67	        if (reservation.status() != ReservationStatus.PENDING) {
    68	            throw notAllowed(reservation, "confirm");
    69	        }
    70	        reservation.confirmPayment();
    71	        store.update(reservation);
    72	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    73	        emailSender.send(
    74	                reservation.guest().email(),
    75	                "Reserva confirmada - " + HOTEL_NAME,
    76	                confirmationEmailBody(reservation, receipt));
    77	        Room room = roomOf(reservation);
    78	        for (ReservationNotification notification : notifications) {
    79	            notification.onConfirmation(reservation, room);
    80	        }
    81	        return reservation;
    82	    }
    83	
    84	    /**
    85	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    86	     * reservation was never paid, so nothing comes back).
    87	     */
    88	    public synchronized Reservation cancel(long reservationId) {
    89	        Reservation reservation = find(reservationId);
    90	        if (reservation.status() != ReservationStatus.PENDING
    91	                && reservation.status() != ReservationStatus.CONFIRMED) {
    92	            throw notAllowed(reservation, "cancel");
    93	        }
    94	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    95	        BigDecimal refund = switch (reservation.ratePlan()) {
    96	            case STANDARD -> reservation.amountPaid();
    97	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    98	        };
    99	        reservation.cancel(refund);
   100	        store.update(reservation);
   101	        if (wasConfirmed) {
   102	            Room room = roomOf(reservation);
   103	            for (ReservationNotification notification : notifications) {
   104	                notification.onCancellation(reservation, room);
   105	            }
   106	        }
   107	        return reservation;
   108	    }
   109	
   110	    public synchronized Reservation checkIn(long reservationId) {
   111	        Reservation reservation = find(reservationId);
   112	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   113	            throw notAllowed(reservation, "check in");
   114	        }
   115	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   116	        store.update(reservation);
   117	        return reservation;
   118	    }
   119	
   120	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   121	    public synchronized ReservationReceipt checkOut(long reservationId) {
   122	        Reservation reservation = find(reservationId);
   123	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   124	            throw notAllowed(reservation, "check out");
   125	        }
   126	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   127	        store.update(reservation);
   128	        return new ReservationReceipt(reservation, roomOf(reservation));
   129	    }
   130	
   131	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   132	    public ReservationReceipt receiptCopy(long reservationId) {
   133	        Reservation reservation = find(reservationId);
   134	        if (!reservation.isPaid()) {
   135	            throw notAllowed(reservation, "issue a receipt for");
   136	        }
   137	        return new ReservationReceipt(reservation, roomOf(reservation));
   138	    }
   139	
   140	    private Room roomOf(Reservation reservation) {
   141	        return rooms.find(reservation.roomNumber()).orElseThrow();
   142	    }
   143	
   144	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   145	        return "Olá, " + reservation.guest().name() + "!\n\n"
   146	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   147	                + receipt.text() + "\n"
   148	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   149	                + "Até breve!\n";
   150	    }
   151	
   152	    private static HotelException notAllowed(Reservation reservation, String operation) {
   153	        return new HotelException(
   154	                ErrorCode.OPERATION_NOT_ALLOWED,
   155	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   156	    }
   157	}
