    18	import org.junit.jupiter.api.AfterEach;
    19	import org.junit.jupiter.api.Test;
    20	
    21	class ReservationServiceTest {
    22	
    23	    private final EmptyDatabase database = new EmptyDatabase();
    24	    private final SentMessages sentMessages = new SentMessages(database.dataSource());
    25	    private final ReservationService service = new ReservationService(
    26	            new Rooms(database.dataSource()),
    27	            new ReservationStore(database.dataSource()),
    28	            new PriceCalculator(),
    29	            new EmailSender(sentMessages),
    30	            Collections.emptyList());
