    34	        database.close();
    35	    }
    36	
    37	    private static NewReservation stay(int roomNumber, String checkIn, String checkOut, int guests, RatePlan plan) {
    38	        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
    39	        return new NewReservation(
    40	                roomNumber, guest, LocalDate.parse(checkIn), LocalDate.parse(checkOut), guests, plan);
    41	    }
    42	
    43	    private static ErrorCode errorOf(Runnable action) {
    44	        return assertThrows(HotelException.class, action::run).errorCode();
    45	    }
    46	
    47	    @Test
    48	    void aNewReservationIsPendingWithItsPrice() {
    49	        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
    50	
    51	        assertEquals(ReservationStatus.PENDING, reservation.status());
    52	        assertEquals(new BigDecimal("749.70"), reservation.price().total());
    53	        assertNull(reservation.refund());
    54	    }
    55	
    56	    @Test
    57	    void refusesInvalidStays() {
    58	        assertEquals(ErrorCode.INVALID_REQUEST,
    59	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-10", 2, RatePlan.STANDARD))));
    60	        assertEquals(ErrorCode.INVALID_REQUEST,
    61	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 0, RatePlan.STANDARD))));
    62	        assertEquals(ErrorCode.ROOM_NOT_FOUND,
    63	                errorOf(() -> service.create(stay(999, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD))));
    64	        assertEquals(ErrorCode.CAPACITY_EXCEEDED,
    65	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 3, RatePlan.STANDARD))));
    66	    }
    67	
    68	    @Test
    69	    void aRoomCannotBeBookedTwiceForTheSameNight() {
    70	        service.create(stay(201, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
    71	
    72	        assertEquals(ErrorCode.ROOM_UNAVAILABLE,
    73	                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.STANDARD))));
    74	        // the check-out day is free for the next guest, and another room is free on the same nights
    75	        service.create(stay(201, "2027-03-13", "2027-03-15", 2, RatePlan.STANDARD));
    76	        service.create(stay(202, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
    77	    }
