    81	        Reservation first = service.create(stay(301, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
    82	        service.cancel(first.id());
    83	
    84	        service.create(stay(301, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
    85	    }
    86	
    87	    @Test
    88	    void confirmingSendsTheReceiptByEmail() {
    89	        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE));
    90	
    91	        service.confirm(reservation.id());
    92	
    93	        assertEquals(ReservationStatus.CONFIRMED, service.find(reservation.id()).status());
    94	        List<Message> sent = sentMessages.all();
    95	        assertEquals(1, sent.size());
    96	        assertEquals("EMAIL", sent.get(0).channel());
    97	        assertEquals("ana@example.com", sent.get(0).to());
    98	        assertEquals("Reserva confirmada - Pousada Maré Alta", sent.get(0).subject());
    99	        assertTrue(sent.get(0).body().contains("Desconto: R$ 37,48"));
   100	        assertTrue(sent.get(0).body().contains("Total: R$ 212,42"));
   101	    }
   102	
   103	    @Test
   104	    void onlyAPendingReservationCanBeConfirmed() {
   105	        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
   106	        service.confirm(reservation.id());
   107	
   108	        assertEquals(ErrorCode.OPERATION_NOT_ALLOWED, errorOf(() -> service.confirm(reservation.id())));
   109	        assertEquals(1, sentMessages.all().size());
   110	    }
   111	
   112	    @Test
   113	    void cancellingGivesTheMoneyBackAccordingToTheRatePlan() {
   114	        Reservation pending = service.create(stay(101, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
   115	        Reservation standard = service.create(stay(102, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));
   116	        Reservation nonRefundable = service.create(stay(201, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE));
   117	        service.confirm(standard.id());
   118	        service.confirm(nonRefundable.id());
   119	
